// CONFIG: describe the client's store in one sentence. Jev uses it as context.
const STORE = "A small online skincare store in New Zealand selling cleansers, serums, moisturisers, night cream and toner.";
const MAX_CHARS = 3000; // long threads cost more and add noise; keep the newest message only

const QUESTIONS = {
  "topic": {
    "type": "choice",
    "instructions": "What is `email.text` mainly about?",
    "criteria": {
      "where_is_order": "An order that has not arrived yet, is late, or has tracking that is stuck",
      "damaged_or_wrong": "An item that arrived broken, leaking, missing, or not what was ordered",
      "refund_return": "Returning an item, exchanging it, cancelling an order, or getting money back",
      "product_question": "How to use a product, its ingredients, whether it suits someone, or its effects on skin or health",
      "other": "None of the above, such as discount codes, address changes, subscriptions, wholesale or business enquiries"
    }
  },
  "urgency": {
    "type": "score",
    "instructions": "How soon does the sender of `email.text` need a reply?",
    "criteria": [
      "No deadline is mentioned or implied",
      "The sender wants a reply soon, but nothing goes wrong if it waits a day",
      "Something goes wrong without a reply today, such as an order about to ship, a deadline today, or a person's health"
    ]
  },
  "frustration": {
    "type": "score",
    "instructions": "How does the sender of `email.text` feel about the store?",
    "criteria": [
      "Friendly or neutral; just asking a question or letting the store know something",
      "Unhappy about a problem but polite, and still expects the store to fix it",
      "Angry, has given up on the store, or says they will stop buying"
    ]
  },
  "safety_issue": {
    "type": "noul",
    "instructions": "Does `email.text` describe possible harm to a person's body?",
    "criteria": {
      "true": "A skin reaction, rash, allergy, injury, cut, burn, or someone swallowing a product",
      "false": "No harm to any person is described; damage to items or packaging alone does not count"
    }
  },
  "legal_or_chargeback": {
    "type": "noul",
    "instructions": "Does `email.text` mention a chargeback, a bank or card dispute, a lawyer, the Commerce Commission, or consumer law?"
  },
  "public_complaint": {
    "type": "noul",
    "instructions": "Does the sender of `email.text` say they might complain publicly, such as posting a bad review or posting on social media?"
  },
  "refund_requested": {
    "type": "noul",
    "instructions": "Is the sender of `email.text` asking for their money back?",
    "criteria": {
      "true": "Asks for a refund, money back, a chargeback, or to cancel an order and be repaid",
      "false": "Does not ask for money back; asking for a replacement or exchange does not count"
    }
  },
  "is_pitch": {
    "type": "noul",
    "instructions": "Is `email.text` from a business offering to sell its own services to the store?",
    "criteria": {
      "true": "An agency, marketer, SEO seller, developer, designer or influencer offering paid work, including free audits or calls that lead to paid work",
      "false": "A customer, or a business that wants to buy or stock the store's products, such as a wholesale enquiry"
    }
  }
};

const e = $json;
const raw = e.text || (e.textAsHtml || e.html || "").replace(/<[^>]+>/g, " ") || e.snippet || "";
// Keep only the newest message: drop quoted history and "On ... wrote:" blocks.
const newest = raw
  .split(/\r?\nOn .+wrote:\r?\n|\r?\n-{2,} ?Original Message|\r?\nFrom: .+\r?\nSent: /)[0]
  .split("\n").filter(line => !line.trim().startsWith(">")).join("\n")
  .trim().slice(0, MAX_CHARS);
const sender = e.from?.value?.[0] ?? {};
const fromName = sender.name || sender.address || e.from?.text || "unknown";

return {
  json: {
    emailId: e.id,
    threadId: e.threadId,
    from: fromName,
    fromAddress: sender.address || "",
    subject: e.subject || "",
    payload: {
      model: "jev-1.13.0", // pinned: the version the 20-email results were recorded on
      state: { store: STORE, email: { from: fromName, subject: e.subject || "", text: newest } },
      questions: QUESTIONS,
    },
  },
};

// Lane rules, ported line for line from triage.py decide(). Order matters:
// safety checks run before anything automated.
const RISK_AT = 0.3, PITCH_AT = 0.8, LO = 0.3, HI = 0.7, TOPIC_CONF_MIN = 0.6;
const RISK_NOULS = {"safety_issue": "health or safety", "legal_or_chargeback": "legal or chargeback", "public_complaint": "public complaint"};
const AUTO_ACTIONS = {"where_is_order": "Auto-reply with live tracking", "damaged_or_wrong": "Auto-reply asking for a photo, priority queue", "refund_return": "Auto-reply with returns form"};
const TOPICS = ["where_is_order", "damaged_or_wrong", "refund_return", "product_question", "other"];

function decide(a) {
  const topic = a.topic.choice, topicConf = a.topic.confidence;
  const pitch = a.is_pitch.noul, refund = a.refund_requested.noul;
  const frustration = a.frustration.score, urgency = a.urgency.score;
  const flagged = Object.keys(RISK_NOULS).filter(q => a[q].noul >= RISK_AT).map(q => RISK_NOULS[q]);

  if (flagged.length) return ["human_now", "Risk flagged: " + flagged.join(", ")];
  if (pitch >= PITCH_AT) return ["archive", "Sales pitch"];
  if (frustration >= 1.5) return ["human_now", "Customer close to leaving"];
  if (refund >= HI && frustration >= 0.75) return ["human_now", "Upset and asking for money back"];
  if (topicConf < TOPIC_CONF_MIN || (LO < pitch && pitch < PITCH_AT) || (LO < refund && refund < HI))
    return ["human_queue", "Model unsure, left for a person"];
  if (topic in AUTO_ACTIONS) return ["auto", AUTO_ACTIONS[topic]];
  if (urgency >= 1.5) return ["human_now", "Needs a reply today"];
  if (topic === "product_question") return ["human_queue", "Product question, reply drafted for review"];
  return ["human_queue", "Needs a person"];
}

// Ported from triage.py validate(): the first unusable field, or null if decide() can read every answer.
// Without this, a missing or non-numeric value fails every comparison and can fall through to Automated.
const isObj = x => x !== null && typeof x === "object" && !Array.isArray(x);
const realIn = (v, lo, hi) => typeof v === "number" && Number.isFinite(v) && v >= lo && v <= hi;

function validate(a) {
  if (!isObj(a)) return "no answers";
  const t = a.topic;
  if (isObj(t) && t.choice !== null && typeof t.choice === "object") return "malformed answer";
  if (!isObj(t) || typeof t.choice !== "string" || !TOPICS.includes(t.choice)) return "topic.choice";
  if (!realIn(t.confidence, 0, 1)) return "topic.confidence";
  for (const q of ["urgency", "frustration"])
    if (!isObj(a[q]) || !realIn(a[q].score, 0, 2)) return `${q}.score`;
  for (const q of [...Object.keys(RISK_NOULS), "refund_requested", "is_pitch"])
    if (!isObj(a[q]) || !realIn(a[q].noul, 0, 1)) return `${q}.noul`;
  return null;
}

// Ported from triage.py decide_safe(): anything missing or unusable goes to a person.
function decideSafe(a) {
  if (a === undefined || a === null) return ["human_queue", "Jev unavailable, left for a person"];
  const field = validate(a);
  if (field) return ["human_queue", `Invalid answer (${field}), left for a person`];
  return decide(a);
}

const a = $json.answers;
const src = $('Build Jev request').item.json;
let lane, reason, valid;
try {
  [lane, reason] = decideSafe(a);
  valid = validate(a) === null;
} catch (err) {
  // Should never happen after validate(), but a crash here would drop the email unlabelled.
  [lane, reason, valid] = ["human_queue", `Decide step error (${err.message}), left for a person`, false];
}

const scores = valid ? {
  topic: a.topic.choice,
  topic_conf: a.topic.confidence,
  urgency: a.urgency.score,
  frustration: a.frustration.score,
  safety: a.safety_issue.noul,
  legal_or_chargeback: a.legal_or_chargeback.noul,
  public_complaint: a.public_complaint.noul,
  refund: a.refund_requested.noul,
  pitch: a.is_pitch.noul,
} : {};

return {
  json: {
    logged_at: new Date().toISOString(),
    lane,
    reason,
    emailId: src.emailId,
    threadId: src.threadId,
    from: src.from,
    fromAddress: src.fromAddress,
    subject: src.subject,
    gmailLink: `https://mail.google.com/mail/u/0/#all/${src.threadId}`,
    ...scores,
    input_tokens: $json.usage?.input_tokens ?? null,
    model: $json.model ?? null,
  },
};

// Jev call failed after 3 tries (timeout, outage, bad key). Send the email to a person.
// Bad answers inside a successful reply are caught by validate() in Decide lane instead.
const src = $('Build Jev request').item.json;
return {
  json: {
    logged_at: new Date().toISOString(),
    lane: "human_queue",
    reason: "Jev unavailable, left for a person",
    emailId: src.emailId,
    threadId: src.threadId,
    from: src.from,
    fromAddress: src.fromAddress,
    subject: src.subject,
    gmailLink: `https://mail.google.com/mail/u/0/#all/${src.threadId}`,
  },
};

